import pandas as pd
import numpy as np

def apply(df, ctx):
    cnorms = (df["cnorm_1"] + df["cnorm_2"]) / 2
    cnorms_z = (cnorms - cnorms.mean()) / cnorms.std(ddof=0)
    return df.assign(cnorms_z=cnorms_z)
